\begin{definition}[Line-point distributions]\label{def:line-point-dist}
	\lean{MIPStarRE.QPBT.LineKind, MIPStarRE.QPBT.LineDesc}
	\lean{MIPStarRE.QPBT.aLinePointDist, MIPStarRE.QPBT.dLinePointDist}
